"""Build a results-driven PDF. Final mode refuses missing Ray results."""
import argparse, math
from pathlib import Path
from xml.sax.saxutils import escape
from reportlab.lib import colors
from reportlab.lib.styles import getSampleStyleSheet,ParagraphStyle
from reportlab.lib.enums import TA_LEFT
from reportlab.lib.pagesizes import letter
from reportlab.platypus import SimpleDocTemplate,Paragraph,Spacer,Table,TableStyle,Image,PageBreak,KeepTogether
from data import load
from plots import make
import numpy as np

def build(root,out,username,repo,final=False):
    root=Path(root);out=Path(out); files=['selection.json','noise_selection.json','serial_test.json','validation.json'];
    missing=[f for f in files if not (out/f).exists()]; ray=load(out/'ray_test.json') if (out/'ray_test.json').exists() else None
    if missing: raise SystemExit('Missing real-data results: '+str(missing))
    if final and ray is None: raise SystemExit('Ray results missing. Run python experiments.py ray --cpus 4 --gpus 0 first.')
    m=load(root/'manifest.json');s=load(out/'selection.json');d=load(out/'noise_selection.json');t=load(out/'serial_test.json');v=load(out/'validation.json');
    if m['synthetic'] or s['dataset']!=m['fingerprint'] or not v['passed']:raise SystemExit('Dataset fingerprint or validation check failed.')
    ids=make(root,out);f=out/'figures'; chosen=s['selected']; w=next(i for i in s['grid'] if i['name']==chosen); base=d['runs'][0]; r=next(i for i in d['runs'] if i['name']==d['recommended']);
    sheet=getSampleStyleSheet(); sheet.add(ParagraphStyle(name='BodyA',fontName='Helvetica',fontSize=10.25,leading=14,spaceAfter=7,textColor=colors.HexColor('#263748')));sheet.add(ParagraphStyle(name='HeadA',fontName='Helvetica-Bold',fontSize=17,leading=21,spaceAfter=10,textColor=colors.HexColor('#173956')));sheet.add(ParagraphStyle(name='SubA',fontName='Helvetica-Bold',fontSize=12,leading=15,spaceBefore=7,spaceAfter=6,textColor=colors.HexColor('#173956')));sheet.add(ParagraphStyle(name='CodeA',fontName='Courier',fontSize=8.1,leading=11,spaceAfter=4,textColor=colors.HexColor('#243b50')));sheet.add(ParagraphStyle(name='CapA',fontSize=9,leading=12,spaceAfter=8,textColor=colors.HexColor('#4f6170')))
    story=[]
    def p(x):story.append(Paragraph(x,sheet['BodyA']))
    def h(x):story.append(Paragraph(x,sheet['HeadA']))
    def sub(x):story.append(Paragraph(x,sheet['SubA']))
    def code(x):story.append(Paragraph(escape(x),sheet['CodeA']))
    def page():story.append(PageBreak())
    def tab(rows,widths):
        data=[[Paragraph(escape(str(x)),ParagraphStyle(name='cell',fontName='Helvetica-Bold' if i==0 else 'Helvetica',fontSize=9,leading=12,textColor=colors.white if i==0 else colors.HexColor('#203447'))) for x in row] for i,row in enumerate(rows)]
        table=Table(data,colWidths=widths,repeatRows=1,hAlign='LEFT');table.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.HexColor('#193d5d')),('ROWBACKGROUNDS',(0,1),(-1,-1),[colors.HexColor('#eef3f7'),colors.white]),('VALIGN',(0,0),(-1,-1),'TOP'),('TOPPADDING',(0,0),(-1,-1),6),('BOTTOMPADDING',(0,0),(-1,-1),6)]));story.extend([table,Spacer(1,9)])
    def fig(name,caption,width=500,maxh=335):
        img=Image(str(f/name));scale=min(width/img.imageWidth,maxh/img.imageHeight);img.drawWidth=img.imageWidth*scale;img.drawHeight=img.imageHeight*scale;story.append(KeepTogether([img,Paragraph(caption,sheet['CapA'])]))
    def pct(x):return f'{100*x:.2f}%'
    h('Assignment 3: Federated learning and differential privacy');p('IEMS 469 | Advanced Algorithms for Machine Learning');p(f'<b>GitHub username:</b> {escape(username)}<br/><b>Repository:</b> {escape(repo)}<br/><b>Public source:</b> https://github.com/{escape(username)}/{escape(repo)}')
    if not ray:p('<b>INCOMPLETE DRAFT:</b> Sequential and noise experiments use the real Canvas dataset. Ray actor training has not been executed in the authoring environment. Do not submit this draft as a completed assignment.')
    else:p('All required experiment groups have recorded results. Verify that the public repository is accessible before submission.')
    sub('Summary of measured outcomes');tab([['Experiment','Result'],['Clean FedAvg, validation-selected model',f"C={w['k']}%, E={w['epochs']}; test {pct(t[chosen]['accuracy'])}"],['Clean validation',pct(w['final']['val_acc'])],['Recommended noise scale',f"b={r['b']:g}; test {pct(t[r['name']]['accuracy'])}"],['Parallel Ray (four clients)',pct(ray['test']['accuracy']) if ray else 'Pending actual run']],[260,240]);
    sub('Reproduction (from repository root)');
    for c in ['python3 -m venv .venv; source .venv/bin/activate','python -m pip install -r requirements.txt','python data.py --data Assignment3-data --out prepared','python -m pytest -q tests/','python validate.py','python experiments.py serial --rounds '+str(s['rounds']),'python experiments.py ray --cpus 4 --gpus 0','python build_report.py --username '+username+' --repo '+repo+' --final']:code(c)
    p('Extract the instructor-provided ZIP first. A compatible Python 3.9+ environment and Ray Core are required; CPU execution is sufficient. The supplied results use seed '+str(s['seed'])+'. Completed configurations are reused; interrupted runs resume committed rounds. To rerun fresh, use a separate --out directory. Raw course data are not included in the public repository.');
    page();h('1. Data distribution and preprocessing');p(f"The Canvas train array stores 100 writer dictionaries. The original development set has {v['total_train']+v['total_val']:,} images; the independently supplied held-out array contains {m['test_n']:,} images. Each writer is partitioned with floor(0.8n) train examples and the remainder validation using a writer-specific deterministic permutation. This gives {v['total_train']:,} training examples and {v['total_val']:,} validation examples. No held-out labels influence model selection. The pixel values are already in [0,1]; we use 1-x to make ink bright and background dark. Class indices are retained as supplied; the archive provides no explicit character-index map.")
    fig('class_counts.png','Figure 1. All development samples, before train/validation splitting. Counts span '+str(v['min_class'])+' to '+str(v['max_class'])+' per class.',maxh=200)
    fig('writer_distribution.png','Figure 2. Five writers chosen deterministically by sample-count quantile: '+', '.join(map(str,ids))+'. Each row sums to 100%.',maxh=200)
    p(f"All {v['class_count']} classes are present globally, but {v['missing_client_class_pairs']} of 6,200 writer-class pairs are absent. Writer sample counts range from {v['min_client']} to {v['max_client']}; median total variation from the global class distribution is {v['median_client_tv']:.3f} (0 means identical). This demonstrates both unequal sample counts and non-IID label proportions.")
    page();h('2. Sequential FedAvg and hyperparameters');p('The classifier is a two-layer dense network: flatten 28 x 28, Linear(784,128), ReLU, Linear(128,62). Output logits feed cross-entropy; accuracy is argmax correctness. Initialize all experiments identically. In round t, randomly sample K distinct writers without replacement. Each receives a copy of the same global parameters, uses local shuffled minibatches of 32 with SGD (learning rate 0.08), and returns parameters and its training sample count. The server computes a sample-weighted average, not a uniform average of models. Raw examples are never passed between client updates.')
    p('<b>Aggregation:</b> w(t+1) = sum_i n_i w_i / sum_i n_i, where n_i counts the selected writer training examples, not epochs or validation examples. Evaluate the resulting global model on every local split by summing cross-entropy losses and correct predictions and dividing by total examples. A single-machine simulation reads each partition locally; this is not a secure distributed data system.')
    rows=[['C / local E','Final train','Final validation','Train loss','Val loss']]
    for x in s['grid']:
        a=x['final'];rows.append([f"{x['k']}% / {x['epochs']}",pct(a['train_acc']),pct(a['val_acc']),f"{a['train_loss']:.3f}",f"{a['val_loss']:.3f}"])
    tab(rows,[112,101,101,93,93]);fig('grid.png','Figure 3. Same initialization, split, and round budget; all local training and clean validation metrics are sample-weighted. Round 0 is before updates.',maxh=315)
    page();h('3. Sequential results and validation design');p(f"Selection uses the final validation accuracy after {s['rounds']} rounds, not test accuracy. The chosen model is C={w['k']}%, E={w['epochs']}. It has {t[chosen]['correct']:,} correct predictions out of {t[chosen]['n']:,} on held-out data ({pct(t[chosen]['accuracy'])}). E=5 gives a substantial gain over E=1 at this round budget for both C settings. The 4% and 10% E=5 models are close; a single seed does not establish the superiority of 10%. A fixed-round comparison also allows different compute and numbers of processed local examples.")
    sub('Controlled quantitative validation beyond unit tests');tab([['Test and prediction','Measured evidence'],['Sample-weighted example: values 1 and 9, counts 1 and 3, expected 7',str(v['analytic_weighted'])],['Identical parameters should remain unchanged',f"L2 error {v['identical_update_l2']:.2e}"],['One full-batch update per real writer equals gradient of sample-weighted objective',f"Weighted L2 error {v['weighted_reference_l2']:.2e}; uniform {v['uniform_reference_l2']:.5f}"],['More local epochs move farther from common initialization',f"E=1 drift {v['drift']['1']:.4f}; E=5 drift {v['drift']['5']:.4f}"],['Local training loss should decrease with additional local work',f"E=1 loss {v['local_loss']['1']:.4f}; E=5 loss {v['local_loss']['5']:.4f}"],['Sample 10 distinct writers randomly per round',f"1,000 rounds; min/max selections {v['sampling_min']}/{v['sampling_max']}; expected 100; no duplicates: {v['sampling_unique']}"],['Train/validation index sets disjoint, exact coverage',str(v['split_disjoint_exact'])]],[285,215]);
    p('The gradient reference is independently calculated from per-writer full-batch cross-entropy gradients, weighted by sample counts. This is an analytical check on real data, not just an array-shape check. The tested writers '+str(v['selected_gradient_clients'])+' have local train counts '+str(v['gradient_n'])+'. Uniform averaging is measurably different because writers have different counts. The E comparison controls initialization, local learning rate and batch order seed. Larger drift can also hurt aggregation on heterogeneous data.')
    page();h('4. Nonstandard diagnostics and edge cases');fig('diagnostics.png','Figure 4. Per-writer validation percentiles and global update cancellation, for the selected clean model.',maxh=210)
    rr=load(out/chosen/'history.json');a=rr[-1];med=float(np.median([j['cancellation'] for j in rr[1:]]));coverage=len({i for j in rr[1:] for i in j['selected']});p(f"At the final round, the 10th/50th/90th percentile writer accuracies are {pct(a['val_client_p10'])}, {pct(a['val_client_median'])} and {pct(a['val_client_p90'])}. Global accuracy can obscure this spread. The global step norm is no larger than the sample-weighted average client step norm (triangle inequality); their ratio has median {med:.3f}. A small ratio means local updates partially cancel, not necessarily a bug. {coverage}/100 writers participated at least once.")
    fig('validation.png','Figure 5. Client selection frequencies and Laplace variance calibration; both are checked quantitatively.',maxh=210)
    p('Edge cases: empty or singleton writers cannot support two nonempty splits and are rejected; a one-class writer still trains with 62 logits; short final batches are used instead of dropped; absent classes do not create invalid accuracy denominators; empty, zero-weight, or nonfinite parameter updates fail explicitly. Sampling is without replacement and rejects invalid counts. A client failure aborts the round without committing a partial aggregate. Fourteen automated tests and the separate controlled validation script are provided.')
    page();h('5. Ray Core: four parallel clients');p('Use Ray Core only. Create a ClientActor for each of the four sampled writers; each actor reserves one CPU and optionally one GPU, loads only its own partition and performs the same local optimizer as serial FedAvg. Broadcast one model object with ray.put, submit update.remote calls, collect all results with ray.get, then kill actors in a finally block. With insufficient CPU/GPU slots, run resource-bounded waves rather than deadlock. Actor creation/destruction is included in measured update time; no actors for unsampled writers persist. CPU workers use one PyTorch thread.')
    if ray:
        tab([['Metric','Measured'],['Held-out test accuracy',pct(ray['test']['accuracy'])],['Serial / Ray validation',f"{pct(ray['serial_val'])} / {pct(ray['ray_val'])}"],['Same client schedules',str(ray['same_schedule'])],['Final parameter L2 difference',f"{ray['final_parameter_l2']:.3e}"],['Serial / Ray update time (s)',f"{ray['serial_update_seconds']:.2f} / {ray['ray_update_seconds']:.2f}"],['Serial / Ray round time (s)',f"{ray['serial_total_seconds']:.2f} / {ray['ray_total_seconds']:.2f}"],['Allocated CPU / GPU slots',f"{ray['cpus']} / {ray['gpus']}"]],[260,240]);fig('ray.png','Figure 6. Matched four-client serial and actor-based FedAvg curves.',maxh=275);p('With CPU execution and matched seeds, close weights and matching curves support semantic equivalence. Small floating-point differences may arise on different devices or software versions. Timings shown are recorded wall times; the packaged serial run and local Ray run may use different machines, so their ratio is not a controlled speedup unless both are rerun on the same machine.')
    else:p('<b>Pending:</b> Ray was unavailable in the execution runtime and could not be installed. No Ray accuracy, speedup, or parallel curves are claimed. Run the experiment locally; the final report will include matched serial scheduling, parameter comparison, loss/accuracy curves and test performance. Do not substitute serial results for Ray results.')
    page();h('6. Laplace input perturbation');p('For each writer, create a fixed noisy training partition X-prime = X + noise, where each coordinate has independent zero-centered Laplace noise of scale b. The noise is added after pixel normalization and inversion, with no clipping; values outside [0,1] are valid. Validation and test images remain clean. A separate clean-training diagnostic is reported. Fixed seeded perturbations avoid accidental repeated noise accumulation and pair the underlying draws across scales for fair utility comparisons. The seed is public for reproducibility, not suitable for a real privacy deployment.')
    rows=[['Scale b','Noisy train','Clean train','Validation','Test']]
    for j in d['runs']:
        z=j['final'];rows.append([f"{j['b']:g}",pct(z['train_acc']),pct(z['clean_train_acc']),pct(z['val_acc']),pct(t[j['name']]['accuracy'])])
    tab(rows,[78,105,101,108,108]);fig('noise_curves.png','Figure 7. Fixed C=10%, E='+str(s['dp_epochs'])+', '+str(s['rounds'])+' rounds; same model initialization and client schedule at all scales.',maxh=180)
    fig('noise_tradeoff.png','Figure 8. Required final training and test accuracy versus b. Clean-training and validation accuracy are included as diagnostic curves.',maxh=175)
    page();h('7. Privacy-utility interpretation and validation');p(f"Recommend b={r['b']:g} for this utility experiment: choose the largest positive tested scale whose validation accuracy is within 3 percentage points of the clean baseline (rule set before looking at held-out results; within tolerance: {d['within_tolerance']}). Validation changes from {pct(base['final']['val_acc'])} to {pct(r['final']['val_acc'])}, and test from {pct(t[base['name']]['accuracy'])} to {pct(t[r['name']]['accuracy'])}. Higher b generally reduces clean validation/test accuracy. At very large noise, the model may partially fit fixed perturbations: noisy training accuracy can exceed clean accuracy, as the table shows. This is not evidence of improved clean generalization.")
    sub('Laplace distribution checks');rows=[['b','Mean','Measured variance','Theory 2b²','Actual image MSE','Out of [0,1]']]
    for q in v['noise']:rows.append([f"{q['b']:g}",f"{q['mean']:.4f}",f"{q['variance']:.4f}",f"{q['expected_variance']:.4f}",f"{q['actual_image_mse']:.4f}",pct(q['outside_unit'])]);
    tab(rows,[48,72,104,86,102,88]);p('The distribution validation uses one million independent scalar draws per scale. The mean should be near zero, variance 2b^2, and mean absolute deviation b. The actual image MSE is also measured on 20 real samples. b=0 is exactly unchanged; negative/nonfinite scales are rejected; the same fixed noise seed reproduces the same array. Unbounded noise is retained rather than silently clipped. The observed noisy-training/clean-validation gap is specific to the chosen fixed-noise design.')
    sub('What privacy can and cannot be claimed');p('For a genuine secret-randomness Laplace release of one normalized image, a one-pixel replacement has L1 sensitivity at most 1 (epsilon at most 1/b). Arbitrary replacement of all 784 pixels has sensitivity at most 784 (epsilon at most 784/b). At b=0.1 the image-level bound is 7,840, which is extremely weak. These conditional textbook bounds do not establish privacy of this experiment: the deterministic public seed, clean labels, raw evaluation metrics, and lack of a defined user-level neighboring relation/accounting preclude a meaningful end-to-end DP guarantee. Federated learning alone is not differential privacy. Do not release raw or noisy client examples, or claim certified privacy. A real deployment would require secret randomness, a defined threat model, privacy accounting, and likely a different mechanism such as clipped client-level updates with calibrated noise. The recommendation balances empirical utility and perturbation only.')
    page();h('8. Extended validation and next experiments');p('Over three additional months I would:')
    for txt in ['Repeat all C/E and noise runs over 10-20 seeds; estimate uncertainty across independently trained models, not solely test samples. Hold out one final evaluation set after selection.','Compare fixed communication rounds against fixed numbers of local SGD steps, sample exposures, and total compute. Tune learning rates and batch sizes using validation only; run 100-500 rounds to separate convergence speed from final quality.','Create controlled synthetic IID and non-IID partitions with known optima to isolate data heterogeneity without redistributing actual private records. Vary client size imbalance, missing classes, dropout and stragglers.','Audit actual parallel timing on the same hardware, with multiple repeats, separate startup/communication/compute timing, CPU utilization, memory use, actor failure and scheduling under constrained resources.','Run fixed-probe gradient consistency checks at multiple rounds and verify the global update norm inequality and sample-weighted metrics. Track per-writer accuracy and worst decile, not only aggregate accuracy.','Compare matched versus independent noise draws at more finely spaced scales near b=0.1. Evaluate privacy against a stated adversary and a formal neighboring relation; investigate membership inference and properly calibrated record- or client-level DP with privacy accounting.','Test repeated data releases, clipping and label confidentiality. Verify that public outputs cannot recreate noise, and use private held-out writers to measure population shift.']:
        p('- '+txt)
    sub('First ten communication rounds (selected clean model)');rows=[['Round','Selected writers','Train acc.','Val acc.']]
    for j in rr[1:11]:rows.append([j['round'],', '.join(map(str,j['selected'])),pct(j['train_acc']),pct(j['val_acc'])]);
    tab(rows,[50,300,75,75]);
    page();h('9. Sources and reproducibility notes');p('Dataset: instructor-provided Assignment3-data.zip (adapted from LEAF, Caldas et al., arXiv:1812.01097). The original train and test arrays contain 100 local writers and one held-out aggregate respectively. Dataset content fingerprint: '+m['fingerprint']+'.')
    p('Ray documentation: https://docs.ray.io/en/latest/ray-core/walkthrough.html and https://docs.ray.io/en/latest/ray-core/actors.html. FedAvg: McMahan et al., Communication-Efficient Learning of Deep Networks from Decentralized Data, AISTATS 2017.')
    p('The run folders contain final model files, configuration JSON, per-round CSV/JSON, validation results, and generated figures. Individual local samples are deliberately excluded. The results report a single training seed; the small held-out dataset estimates accuracy for this particular model, not independent-training uncertainty. Reproduce the same partition with seed 2026 and the supplied archive. The code simulates local evaluation in one process; no production security boundary is asserted.')
    if not ray:p('<b>Remaining submission requirement:</b> execute the Ray actor experiment before generating the final PDF. The draft must not be represented as a finished assignment.')
    def footer(c,doc):
        c.setStrokeColor(colors.HexColor('#c6d4df'));c.line(48,43,564,43);c.setFont('Helvetica',8);c.setFillColor(colors.HexColor('#5a6e7f'));c.drawString(48,30,'IEMS 469 | Assignment 3'+(' | DRAFT: Ray pending' if not ray else ''));c.drawRightString(564,30,f'Page {doc.page}')
    dest=Path('assignment3_report.pdf' if final else 'assignment3_report_DRAFT.pdf');doc=SimpleDocTemplate(str(dest),pagesize=letter,rightMargin=56,leftMargin=56,topMargin=46,bottomMargin=57,title='Assignment 3 - Federated Learning and Differential Privacy');doc.build(story,onFirstPage=footer,onLaterPages=footer);print('Created',dest,'Ray complete:',bool(ray))
if __name__=='__main__':
    p=argparse.ArgumentParser();p.add_argument('--data',default='prepared');p.add_argument('--out',default='runs');p.add_argument('--username',default='Eddiesg666');p.add_argument('--repo',default='IEMS469-Assignment3');p.add_argument('--final',action='store_true');a=p.parse_args();build(a.data,a.out,a.username,a.repo,a.final)
